import type { BottomSheetBackgroundProps as GorhomBottomSheetBackgroundProps } from "@gorhom/bottom-sheet";
import type { ReactElement } from "react";
import { View } from "react-native";
import { bottomSheetVariants } from "./bottom-sheet.variants";

export type BottomSheetBackgroundProps = Partial<GorhomBottomSheetBackgroundProps> & {
	className?: string;
};

/**
 * The sheet's own surface, drawn behind the handle and the content.
 *
 * Supplied to gorhom as `backgroundComponent` rather than styled through
 * `backgroundStyle`, so the surface is a className like every other surface in
 * this package — and so `backgroundClassName` on `BottomSheet.Container` has
 * something to reach. A `backgroundStyle` a caller passes still arrives, merged
 * into the `style` below.
 *
 * **Forwarding `style` is load-bearing.** gorhom hands this component
 * `[StyleSheet.absoluteFill, backgroundStyle]`; drop it and the surface collapses
 * to nothing and the sheet renders transparent over the app.
 *
 * The two animated variables are destructured off rather than spread: they are
 * shared values, and a `View` has no use for either.
 */
export function BottomSheetBackground({
	animatedIndex: _animatedIndex,
	animatedPosition: _animatedPosition,
	className,
	style,
	...props
}: BottomSheetBackgroundProps): ReactElement {
	return <View className={bottomSheetVariants().background({ className })} style={style} {...props} />;
}
BottomSheetBackground.displayName = "DelacourUI.BottomSheet.Background";

import { type ReactElement, useCallback } from "react";
import { IconCrossSmall } from "@registry/icons/central";
import { Icon } from "@registry/ui/icon";
import { Pressable, type PressableProps } from "@registry/ui/pressable";
import { useBottomSheetPart } from "./bottom-sheet.context";
import { BOTTOM_SHEET_CLOSE_HIT_SLOP, bottomSheetVariants } from "./bottom-sheet.variants";

export type BottomSheetCloseProps = Omit<PressableProps, "asChild" | "busy" | "children" | "disabled">;

/**
 * The sheet's dismiss control.
 *
 * Positioned out of the content's flow, in the top-right of the sheet, so it does
 * not push the title down or take a row of its own. `BottomSheet.Title` reserves
 * the clearance for it on every sheet — see `bottomSheetVariants`.
 *
 * Closing goes through the same `onOpenChange` a swipe-down and a backdrop press
 * do, so a caller has one callback to watch rather than three.
 *
 * `fade` rather than a spring: a scale on a glyph this small reads as a jitter,
 * the reason `Badge.CloseButton` presses the same way. The slop is there because
 * a bare glyph in a corner has no padded capsule to bring it up to the 44pt
 * minimum — the case `Checkbox` mints slop for.
 *
 * @example
 * <BottomSheet.Content>
 *   <BottomSheet.Close />
 *   <BottomSheet.Title>Filters</BottomSheet.Title>
 * </BottomSheet.Content>
 */
export function BottomSheetClose({
	accessibilityLabel = "Close",
	className,
	feedback = "fade",
	hitSlop = BOTTOM_SHEET_CLOSE_HIT_SLOP,
	onPress,
	...props
}: BottomSheetCloseProps): ReactElement {
	const { close } = useBottomSheetPart("BottomSheet.Close");

	const handlePress = useCallback(() => {
		close();
		onPress?.();
	}, [close, onPress]);

	return (
		<Pressable
			accessibilityLabel={accessibilityLabel}
			accessibilityRole="button"
			className={bottomSheetVariants().close({ className })}
			feedback={feedback}
			hitSlop={hitSlop}
			onPress={handlePress}
			{...props}
		>
			<Icon color="muted-foreground" icon={IconCrossSmall} />
		</Pressable>
	);
}
BottomSheetClose.displayName = "DelacourUI.BottomSheet.Close";

import {
	type BottomSheetBackdropProps,
	BottomSheetModal,
	type BottomSheetModalProps,
	type BottomSheetBackgroundProps as GorhomBottomSheetBackgroundProps,
	type BottomSheetFooterProps as GorhomBottomSheetFooterProps,
	type BottomSheetHandleProps as GorhomBottomSheetHandleProps,
} from "@gorhom/bottom-sheet";
import {
	Children,
	cloneElement,
	isValidElement,
	type ReactElement,
	type ReactNode,
	useCallback,
	useEffect,
	useMemo,
	useRef,
} from "react";
import { useSharedValue } from "react-native-reanimated";
import { useKeyboardAnimationGuard } from "@registry/hooks/use-keyboard-state-sync";
import {
	BottomSheetContainerProvider,
	BottomSheetProvider,
	useBottomSheetPart,
	useBottomSheetPortalContext,
} from "./bottom-sheet.context";
import {
	BOTTOM_SHEET_KEYBOARD_DEFAULTS,
	type BottomSheetFooterFlag,
	type BottomSheetFooterPlacement,
	resolveFooterPlacement,
} from "./bottom-sheet.variants";
import { BottomSheetBackground } from "./bottom-sheet-background";
import { BottomSheetFooter, type BottomSheetFooterProps } from "./bottom-sheet-footer";
import { BottomSheetHandle } from "./bottom-sheet-handle";

export type BottomSheetContainerProps = Omit<
	BottomSheetModalProps,
	"backdropComponent" | "backgroundComponent" | "children" | "footerComponent" | "handleComponent" | "onDismiss" | "ref"
> & {
	children?: ReactNode;
	/** Classes for the sheet's surface — the box behind the handle and the content. */
	backgroundClassName?: string;
	/** Classes for the row the grabber sits in. */
	handleClassName?: string;
	/** Classes for the grabber itself. */
	handleIndicatorClassName?: string;
};

/**
 * The sheet itself: the surface that slides up, and everything inside it.
 *
 * Every gorhom prop passes through, so snap points, dynamic sizing, the pan
 * gestures and the animation configs are all reachable. Four are not, because
 * this component supplies them: the backdrop and the footer are cloned from the
 * parts a caller wrote, and the background and the handle are rendered as views
 * of this package's own so they can take a `className` rather than a style.
 *
 * **It takes no `className`.** gorhom's modal wears an animated style that the
 * sheet's own position writes to every frame, so there is nothing here for a
 * class to reach that `backgroundClassName` does not already reach better. The
 * same trade `Screen.Footer` makes — that file takes a `style` and never a
 * `className`, and so wraps nothing in `withUniwind`.
 *
 * **Presenting is driven by state, never by the ref.** `isOpen` on the root is
 * the one source, so a swipe-down, a backdrop press, `BottomSheet.Close` and a
 * programmatic close all arrive at the same `onOpenChange`. gorhom's own
 * `onDismiss` is therefore not forwarded: two callbacks for one event is two
 * things that can disagree. `useBottomSheet().sheetRef` is still there for the
 * imperative calls with no declarative form — `snapToIndex`, `expand`.
 *
 * **`accessible` defaults to `false`, and that is not a small thing.** gorhom
 * marks the sheet's content container `accessible` with the label "Bottom
 * Sheet" and the `adjustable` role. On iOS an `accessible` container collapses
 * its whole subtree into ONE element, so every field, button and line of copy in
 * the sheet becomes unreachable to VoiceOver — a form in a sheet cannot be
 * filled in at all. This is `Field`'s rule one component along: the row is
 * `accessible={false}` so the control stays the element a screen reader sees.
 * Pass `accessible` to opt back into gorhom's behaviour for a sheet whose body
 * really is one adjustable thing.
 *
 * Three defaults differ from gorhom's. `enablePanDownToClose` is on, because a
 * modal sheet has no collapsed resting state to pan down to. And the keyboard
 * trio comes from `BOTTOM_SHEET_KEYBOARD_DEFAULTS` — see that const for why
 * Android must not be left on `adjustPan`. Both are ordinary props, so either
 * can be turned back off.
 *
 * @example
 * <BottomSheet.Container>
 *   <BottomSheet.Content>{…}</BottomSheet.Content>
 * </BottomSheet.Container>
 *
 * @example
 * // A scrollable sheet needs a fixed height to scroll within.
 * <BottomSheet.Container enableDynamicSizing={false} snapPoints={["50%", "90%"]}>
 *   <BottomSheet.ScrollView>{rows}</BottomSheet.ScrollView>
 *   <BottomSheet.Footer sticky>{actions}</BottomSheet.Footer>
 * </BottomSheet.Container>
 */
export function BottomSheetContainer({
	accessible = false,
	backgroundClassName,
	children,
	enablePanDownToClose = true,
	handleClassName,
	handleIndicatorClassName,
	...props
}: BottomSheetContainerProps): ReactElement {
	const sheet = useBottomSheetPart("BottomSheet.Container");
	const { isOpen, setOpen, sheetRef } = sheet;
	const portal = useBottomSheetPortalContext();
	// A sheet that opens while `KeyboardProvider`'s shared values are pinned open
	// by a keyboard that vanished without a `will` event would size itself for a
	// keyboard that is not there. `Screen.Footer` runs the same repair on mount.
	useKeyboardAnimationGuard();

	// Whether this sheet has ever been presented. A JS ref rather than state:
	// nothing renders differently for it, and it has to be readable inside the
	// effect that sets it.
	const hasPresentedRef = useRef(false);

	const { content, footer, placement } = useMemo(() => hoistFooter(children), [children]);
	const hasStickyFooter = placement === "sticky";
	const overlay = portal?.overlay ?? null;

	// Written by the pinned footer's own onLayout, read by the body's spacer. It
	// lives here because the two are siblings in gorhom's tree and neither can see
	// the other — the footer is rendered outside the children this file wraps.
	const footerHeight = useSharedValue(0);

	const containerValue = useMemo(() => ({ footerHeight, hasStickyFooter }), [footerHeight, hasStickyFooter]);

	const backdropComponent = useMemo(
		() =>
			overlay === null ? undefined : (backdropProps: BottomSheetBackdropProps) => cloneElement(overlay, backdropProps),
		[overlay]
	);

	const footerComponent = useMemo(
		() =>
			footer === null
				? undefined
				: (footerProps: GorhomBottomSheetFooterProps) => cloneElement(footer, { ...footerProps, footerHeight }),
		[footer, footerHeight]
	);

	const backgroundComponent = useCallback(
		(backgroundProps: GorhomBottomSheetBackgroundProps) => (
			<BottomSheetBackground {...backgroundProps} className={backgroundClassName} />
		),
		[backgroundClassName]
	);

	const handleComponent = useCallback(
		(handleProps: GorhomBottomSheetHandleProps) => (
			<BottomSheetHandle {...handleProps} className={handleClassName} indicatorClassName={handleIndicatorClassName} />
		),
		[handleClassName, handleIndicatorClassName]
	);

	const handleDismiss = useCallback(() => {
		hasPresentedRef.current = false;
		setOpen(false);
	}, [setOpen]);

	useEffect(() => {
		if (isOpen) {
			hasPresentedRef.current = true;
			sheetRef.current?.present();
			return;
		}

		// Dismissing a modal that was never presented is NOT a no-op, and this is
		// the sharpest edge in the component. gorhom's modal starts at status
		// `INITIAL`; `dismiss()` reads that as a live sheet being closed and moves
		// it to `DISMISSING`, where it stays. The next `present()` then mounts the
		// portal and renders the sheet — and it never animates in, never lays out
		// its content, and never fires `onChange`. Nothing is logged, nothing
		// throws, and the screen simply does not change.
		if (!hasPresentedRef.current) return;
		hasPresentedRef.current = false;
		sheetRef.current?.dismiss();
	}, [isOpen, sheetRef]);

	return (
		<BottomSheetModal
			accessible={accessible}
			backdropComponent={backdropComponent}
			backgroundComponent={backgroundComponent}
			enablePanDownToClose={enablePanDownToClose}
			footerComponent={footerComponent}
			handleComponent={handleComponent}
			onDismiss={handleDismiss}
			ref={sheetRef}
			{...BOTTOM_SHEET_KEYBOARD_DEFAULTS}
			{...props}
		>
			<BottomSheetProvider value={sheet}>
				<BottomSheetContainerProvider value={containerValue}>{content}</BottomSheetContainerProvider>
			</BottomSheetProvider>
		</BottomSheetModal>
	);
}
BottomSheetContainer.displayName = "DelacourUI.BottomSheet.Container";

/**
 * Splits a container's children into the body and a footer to be pinned.
 *
 * gorhom takes a footer as a `footerComponent` render prop rather than as a
 * child, so a sticky one has to leave the tree it was written in; an inline one
 * stays put and is simply part of the body. {@link resolveFooterPlacement} is the
 * decision and is pure, so `bun test` reaches the whole matrix — this walk only
 * turns children into the flags it reads.
 *
 * Lives here rather than with the parts: it is the container that lifts its own
 * children, and importing it from `bottom-sheet-footer.tsx` would close a cycle.
 * See AGENTS.md.
 */
function hoistFooter(children: ReactNode): {
	content: ReactNode;
	footer: ReactElement<BottomSheetFooterProps> | null;
	placement: BottomSheetFooterPlacement;
} {
	const items = Children.toArray(children);
	const flags: BottomSheetFooterFlag[] = [];
	let footer: ReactElement<BottomSheetFooterProps> | null = null;

	for (const child of items) {
		if (!isValidElement(child) || child.type !== BottomSheetFooter) {
			flags.push({ isFooter: false, isSticky: false });
			continue;
		}

		const element = child as ReactElement<BottomSheetFooterProps>;
		const isSticky = element.props.sticky === true;
		flags.push({ isFooter: true, isSticky });
		if (isSticky) footer ??= element;
	}

	const placement = resolveFooterPlacement(flags);
	if (placement !== "sticky" || footer === null) return { content: items, footer: null, placement };

	return { content: items.filter((child) => child !== footer), footer, placement };
}

import { BottomSheetView } from "@gorhom/bottom-sheet";
import type { ReactElement } from "react";
import { View, type ViewProps } from "react-native";
import Animated, { useAnimatedStyle } from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useBottomSheetContainerContext } from "./bottom-sheet.context";
import { BOTTOM_SHEET_FOOTER_GAP, bottomSheetVariants, resolveSheetBottomInset } from "./bottom-sheet.variants";

export type BottomSheetContentProps = ViewProps & {
	className?: string;
};

/**
 * The sheet's body — what a caller writes the title, the copy and the controls
 * into.
 *
 * Two boxes, and neither is a `withUniwind` wrapper. gorhom's `BottomSheetView`
 * is the outer one: it measures itself into the sheet's layout state, which is
 * what makes `enableDynamicSizing` size the sheet to whatever is inside. The
 * inner `View` is an ordinary React Native one and carries every class, so this
 * file wraps nothing — the same move `Screen.Footer` makes with
 * `KeyboardStickyView`.
 *
 * **A pinned footer is reserved by a spacer, not by gorhom's
 * `enableFooterMarginAdjustment`.** That prop turns the footer's measured height
 * into content-container padding through React state — a commit on every frame
 * of the keyboard animation, because the footer changes height as it gives up
 * its safe-area band. A spacer whose height is an animated style off the same
 * shared value costs nothing on the JS thread, and `Screen` already reserves its
 * own chrome exactly this way. The spacer sits OUTSIDE the classed box so the
 * content's own `gap` does not land in front of it and quietly double the
 * {@link BOTTOM_SHEET_FOOTER_GAP} the footer is held off by.
 *
 * **The safe-area band goes on the OUTER box, and only when nothing else is
 * paying for it** — a pinned footer's own box carries it, so
 * {@link resolveSheetBottomInset} withholds it here. The band comes from
 * `useSafeAreaInsets()` and never from `pb-safe`, which compiles to
 * `env(safe-area-inset-bottom)` and resolves to zero on React Native.
 *
 * @example
 * <BottomSheet.Content>
 *   <BottomSheet.Title>Delete this file?</BottomSheet.Title>
 *   <BottomSheet.Description>This cannot be undone.</BottomSheet.Description>
 * </BottomSheet.Content>
 */
export function BottomSheetContent({ className, children, style, ...props }: BottomSheetContentProps): ReactElement {
	const container = useBottomSheetContainerContext();
	const { bottom } = useSafeAreaInsets();
	const hasStickyFooter = container?.hasStickyFooter ?? false;
	const footerHeight = container?.footerHeight;
	const paddingBottom = resolveSheetBottomInset({ bottom, hasStickyFooter });

	const reserve = useAnimatedStyle(() => ({
		height: footerHeight === undefined ? 0 : footerHeight.value + BOTTOM_SHEET_FOOTER_GAP,
	}));

	return (
		<BottomSheetView style={{ paddingBottom }}>
			<View className={bottomSheetVariants().content({ className })} style={style} {...props}>
				{children}
			</View>
			{hasStickyFooter ? <Animated.View style={reserve} /> : null}
		</BottomSheetView>
	);
}
BottomSheetContent.displayName = "DelacourUI.BottomSheet.Content";

import type { ReactElement } from "react";
import { cn } from "@registry/lib/cn";
import { Text, type TextPresetProps } from "@registry/ui/text";

export type BottomSheetDescriptionProps = TextPresetProps;

/**
 * Supporting copy under the sheet's title.
 *
 * *Is* a `Text.Paragraph`, defaulting to the muted token — the title is what the
 * sheet is about and this is what it means, so the two need to read as a
 * hierarchy rather than as two equal lines. `color` is an ordinary prop, so a
 * description that needs the page colour asks for it.
 *
 * It has no slot in `bottomSheetVariants`, and that is deliberate: it carries no
 * layout of its own, and `tv` emits `undefined` for an empty class string, so a
 * slot here would be one nothing could assert against.
 *
 * @example
 * <BottomSheet.Description>Update to the latest version.</BottomSheet.Description>
 */
export function BottomSheetDescription({
	className,
	color = "muted",
	...props
}: BottomSheetDescriptionProps): ReactElement {
	return <Text.Paragraph className={cn(className)} color={color} {...props} />;
}
BottomSheetDescription.displayName = "DelacourUI.BottomSheet.Description";

import { BottomSheetFooter as GorhomBottomSheetFooter } from "@gorhom/bottom-sheet";
import { type ComponentProps, type ReactElement, type ReactNode, useCallback, useEffect } from "react";
import { type LayoutChangeEvent, View, type ViewProps } from "react-native";
import { useReanimatedKeyboardAnimation } from "react-native-keyboard-controller";
import Animated, { type SharedValue, useAnimatedStyle } from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { BOTTOM_SHEET_FOOTER_PADDING, bottomSheetVariants } from "./bottom-sheet.variants";

type GorhomFooterProps = ComponentProps<typeof GorhomBottomSheetFooter>;

export type BottomSheetFooterProps = Omit<ViewProps, "children"> & {
	/**
	 * Pin the footer to the bottom of the sheet, above the keyboard, instead of
	 * leaving it in the content's flow.
	 *
	 * Off by default, matching `Screen.Footer` — a footer holding a submit button
	 * under a short sheet wants to sit where it was written, and a sheet only
	 * needs the pinned treatment once its body can scroll under one.
	 *
	 * @default false
	 */
	sticky?: boolean;
	className?: string;
	children?: ReactNode;
	/**
	 * The sheet's own footer position. Injected by `BottomSheet.Container` when it
	 * hoists a sticky footer; never written at a call site.
	 */
	animatedFooterPosition?: GorhomFooterProps["animatedFooterPosition"];
	/**
	 * Where this footer publishes its measured height. Injected alongside the
	 * position, and read by whatever the sheet's body is so it can reserve exactly
	 * what the footer covers. Never written at a call site.
	 */
	footerHeight?: SharedValue<number>;
};

/**
 * A row of controls at the bottom of the sheet — pinned, or in the flow.
 *
 * **A sticky footer is not rendered where it is written.** gorhom takes it as a
 * `footerComponent` render prop rather than as a child, so
 * `BottomSheet.Container` lifts this element out of its children and clones it
 * into that slot with the sheet's animated footer position attached. An inline
 * footer needs none of that and stays exactly where it was put.
 *
 * The two branches deliberately look different. An inline footer is in the flow
 * and inherits the sheet's surface; a pinned one draws OVER the content, so it
 * brings a background and a top hairline of its own — without them the content
 * scrolls straight through it and its buttons are legible only where they happen
 * to overlap blank space. That is `Screen.Footer`'s rule about its backing, one
 * component along.
 *
 * **A pinned footer is TALLER by the safe-area band; it is not moved up by it.**
 * gorhom's own `bottomInset` translates the whole footer up instead, which
 * leaves a band the height of the home indicator between the footer and the
 * bottom of the sheet — and the content scrolls through it in plain view. So
 * `bottomInset` stays 0 and the band becomes the footer's own `paddingBottom`,
 * which puts its surface against the bottom of the screen where it belongs.
 *
 * The keyboard then needs that band back, and **only that band**. Its own
 * padding stays, so the controls never end up flush against the keyboard, and
 * the footer genuinely gets shorter rather than sliding down — which is what
 * lets the body's reserve shrink with it instead of over-reserving by the height
 * of a home indicator that is no longer there.
 *
 * It publishes its measured height into the sheet, and `BottomSheet.Content` and
 * `BottomSheet.ScrollView` reserve exactly that plus a gap. The height is a
 * shared value read by an animated spacer, never content-container padding —
 * `Screen` reserves its own chrome the same way and for the same reason.
 *
 * **Do not put a `KeyboardStickyView` in here.** gorhom's `animatedFooterPosition`
 * already carries the footer clear of the keyboard; this translate only gives up
 * the safe-area band on top of that. A third mechanism moving the same view
 * would fight both for prop ownership every frame.
 *
 * Written with `sticky` but rendered outside a container, it falls back to the
 * inline branch rather than throwing: there is no footer position to ride, and a
 * row of buttons in the flow is the useful failure.
 *
 * @example
 * <BottomSheet.Footer>
 *   <Button onPress={save}>Save</Button>
 * </BottomSheet.Footer>
 *
 * @example
 * <BottomSheet.Footer sticky>
 *   <Button onPress={submit}>Submit</Button>
 * </BottomSheet.Footer>
 */
export function BottomSheetFooter({
	animatedFooterPosition,
	className,
	children,
	footerHeight,
	onLayout,
	sticky = false,
	style,
	...props
}: BottomSheetFooterProps): ReactElement {
	const { bottom } = useSafeAreaInsets();
	const { progress } = useReanimatedKeyboardAnimation();
	const slots = bottomSheetVariants();

	// The footer keeps its own padding and gives up only the safe-area band, which
	// collapses as the keyboard arrives. `progress` runs 0 → 1 over the keyboard's
	// own animation, so the two travel together.
	const padding = useAnimatedStyle(() => ({
		paddingBottom: BOTTOM_SHEET_FOOTER_PADDING + bottom * (1 - progress.value),
		paddingTop: BOTTOM_SHEET_FOOTER_PADDING,
	}));

	const handleLayout = useCallback(
		(event: LayoutChangeEvent) => {
			if (footerHeight) footerHeight.value = event.nativeEvent.layout.height;
			onLayout?.(event);
		},
		[footerHeight, onLayout]
	);

	useEffect(() => {
		return () => {
			if (footerHeight) footerHeight.value = 0;
		};
	}, [footerHeight]);

	if (!sticky || animatedFooterPosition === undefined) {
		return (
			<View className={slots.footer({ className })} style={style} {...props}>
				{children}
			</View>
		);
	}

	return (
		<GorhomBottomSheetFooter animatedFooterPosition={animatedFooterPosition} bottomInset={0}>
			<Animated.View
				className={slots.stickyFooter({ className })}
				onLayout={handleLayout}
				style={[padding, style]}
				{...props}
			>
				{children}
			</Animated.View>
		</GorhomBottomSheetFooter>
	);
}
BottomSheetFooter.displayName = "DelacourUI.BottomSheet.Footer";

import type { BottomSheetHandleProps as GorhomBottomSheetHandleProps } from "@gorhom/bottom-sheet";
import type { ReactElement } from "react";
import { View, type ViewProps } from "react-native";
import { bottomSheetVariants } from "./bottom-sheet.variants";

export type BottomSheetHandleProps = Partial<GorhomBottomSheetHandleProps> &
	Omit<ViewProps, "children"> & {
		className?: string;
		/** Style for the pill itself. What gorhom's `handleIndicatorStyle` becomes. */
		indicatorStyle?: ViewProps["style"];
		indicatorClassName?: string;
	};

/**
 * The grabber at the top of the sheet.
 *
 * Supplied to gorhom as `handleComponent` for the same reason the background is:
 * this package paints with classNames, and gorhom's `handleStyle` /
 * `handleIndicatorStyle` cannot carry one. Both still arrive — gorhom passes
 * them down as `style` and `indicatorStyle` — so a caller who has a style object
 * rather than a class is not locked out.
 *
 * The pill is drawn but never announced: gorhom's own handle container wraps this
 * in the `Animated.View` that owns the pan and carries the accessibility surface,
 * so a second announced element here would put a nameless control in front of
 * every sheet.
 *
 * The two animated variables are destructured off rather than spread — see
 * `BottomSheetBackground`.
 */
export function BottomSheetHandle({
	animatedIndex: _animatedIndex,
	animatedPosition: _animatedPosition,
	className,
	indicatorClassName,
	indicatorStyle,
	...props
}: BottomSheetHandleProps): ReactElement {
	const slots = bottomSheetVariants();

	return (
		<View className={slots.handle({ className })} {...props}>
			<View className={slots.handleIndicator({ className: indicatorClassName })} style={indicatorStyle} />
		</View>
	);
}
BottomSheetHandle.displayName = "DelacourUI.BottomSheet.Handle";

import {
	BottomSheetBackdrop,
	type BottomSheetBackdropProps,
	useBottomSheet as useGorhomBottomSheet,
} from "@gorhom/bottom-sheet";
import type { ReactElement, ReactNode } from "react";
import { StyleSheet } from "react-native";
import Animated, { useAnimatedStyle } from "react-native-reanimated";
import { withUniwind } from "uniwind";
import { Pressable } from "@registry/ui/pressable";
import {
	BOTTOM_SHEET_BACKDROP_INDICES,
	BOTTOM_SHEET_OVERLAY_OPACITY,
	bottomSheetVariants,
} from "./bottom-sheet.variants";

/**
 * gorhom's backdrop is third-party and takes a `style`, never a `className`, and
 * it is a leaf — there is no inner view to hang classes on the way
 * `BottomSheet.Content` and `BottomSheet.Footer` do. So it is wrapped, once, at
 * module scope. In render `withUniwind` would mint a new component type every
 * frame and remount the scrim mid-fade. See AGENTS.md rule 7.
 */
const StyledBackdrop = withUniwind(BottomSheetBackdrop);

export type BottomSheetOverlayProps = Partial<BottomSheetBackdropProps> & {
	className?: string;
	/**
	 * Opacity at full appearance.
	 *
	 * Defaults to 1 rather than gorhom's 0.5, because `--color-overlay` carries
	 * its own alpha — the two would otherwise multiply and land the scrim at a
	 * fifth of what the theme asked for.
	 */
	opacity?: number;
	/** Snap index the scrim is fully in by. @default 0, the first snap point */
	appearsOnIndex?: number;
	/** Snap index the scrim is gone by. @default -1, the closed position */
	disappearsOnIndex?: number;
	/** Let touches reach the app behind the scrim. @default false */
	enableTouchThrough?: boolean;
	/** Close the sheet when the scrim is pressed. @default true */
	isCloseOnPress?: boolean;
	/** Announced on the pressable scrim. Ignored when it does not close. */
	accessibilityLabel?: string;
	onPress?: () => void;
	children?: ReactNode;
};

/**
 * The scrim over the app behind the sheet.
 *
 * **It is not rendered where it is written.** gorhom takes the backdrop as a
 * `backdropComponent` render prop rather than as a child, so
 * `BottomSheet.Portal` lifts this element out of its own children, publishes it
 * on context, and `BottomSheet.Container` clones it into that slot with the
 * sheet's animated position attached. Writing it as a sibling of the container is
 * what makes the anatomy read like the thing it draws.
 *
 * Omit it and the sheet has no scrim at all — gorhom's own default for
 * `backdropComponent` is nothing.
 *
 * **gorhom's own press handling is deliberately turned off, and the press area
 * is rebuilt here.** Its backdrop puts a full-screen `Gesture.Tap()` behind the
 * sheet, and Gesture Handler resolves a touch between competing GESTURES: a
 * `Button` in the sheet has one of its own and wins, but a `TextInput` has none,
 * so the backdrop takes the tap and the sheet closes instead of the field
 * focusing. That is why gorhom ships its own `BottomSheetTextInput` — and taking
 * that route would mean this package's `Input`, with its variants, its
 * `Input.Group` and its `Field` cascade, could not be used in a sheet at all.
 *
 * So the scrim keeps `pressBehavior="none"` — no gesture anywhere — and a
 * `Pressable` is laid over the region ABOVE the sheet, sized from the sheet's own
 * `animatedPosition`. It never overlaps the sheet, so there is nothing for it to
 * take, and pressing the part of the scrim anyone can actually see still closes.
 * The colour and the fade stay gorhom's, driven off the sheet's position on the
 * UI thread; the slot therefore carries no `opacity-*`, or a class and an
 * animated style would be two writers of one property.
 *
 * @example
 * <BottomSheet.Overlay />
 *
 * @example
 * // A scrim that does not close the sheet — a decision the caller has to make.
 * <BottomSheet.Overlay isCloseOnPress={false} />
 */
export function BottomSheetOverlay({
	accessibilityLabel = "Close",
	animatedIndex,
	animatedPosition,
	appearsOnIndex = BOTTOM_SHEET_BACKDROP_INDICES.appearsOnIndex,
	className,
	disappearsOnIndex = BOTTOM_SHEET_BACKDROP_INDICES.disappearsOnIndex,
	isCloseOnPress = true,
	opacity = BOTTOM_SHEET_OVERLAY_OPACITY,
	onPress,
	...props
}: BottomSheetOverlayProps): ReactElement {
	if (animatedIndex === undefined || animatedPosition === undefined) {
		throw new Error(
			"BottomSheet.Overlay must be written inside a <BottomSheet.Portal>, beside its <BottomSheet.Container>."
		);
	}

	return (
		<>
			<StyledBackdrop
				animatedIndex={animatedIndex}
				animatedPosition={animatedPosition}
				appearsOnIndex={appearsOnIndex}
				className={bottomSheetVariants().overlay({ className })}
				disappearsOnIndex={disappearsOnIndex}
				opacity={opacity}
				pressBehavior="none"
				{...props}
			/>
			{isCloseOnPress ? (
				<BottomSheetOverlayPressArea
					accessibilityLabel={accessibilityLabel}
					animatedPosition={animatedPosition}
					onPress={onPress}
				/>
			) : null}
		</>
	);
}
BottomSheetOverlay.displayName = "DelacourUI.BottomSheet.Overlay";

/**
 * The pressable band between the top of the screen and the top of the sheet.
 *
 * Its height is the sheet's own `animatedPosition`, so it grows and shrinks with
 * the sheet on the UI thread and stops exactly where the sheet begins — which is
 * the whole point. The `Pressable` is a child rather than the animated view
 * itself because `Pressable` takes no `style`: its own `Animated.View` already
 * owns one, and a second would fight it for prop ownership every frame.
 *
 * It reads gorhom's `useBottomSheet()` rather than this package's. The backdrop
 * is rendered by gorhom's own container, OUTSIDE the children
 * `BottomSheet.Container` re-publishes its context around, so the sheet's own
 * handle is the one thing in scope here — and closing through it lands on
 * `onDismiss`, which is where `onOpenChange` already is.
 */
function BottomSheetOverlayPressArea({
	accessibilityLabel,
	animatedPosition,
	onPress,
}: {
	accessibilityLabel: string;
	animatedPosition: NonNullable<BottomSheetBackdropProps["animatedPosition"]>;
	onPress?: () => void;
}): ReactElement {
	const { close } = useGorhomBottomSheet();

	const style = useAnimatedStyle(() => ({ height: Math.max(0, animatedPosition.value) }));

	const handlePress = () => {
		onPress?.();
		close();
	};

	return (
		<Animated.View style={[styles.pressArea, style]}>
			<Pressable
				accessibilityLabel={accessibilityLabel}
				accessibilityRole="button"
				className="flex-1"
				feedback="none"
				onPress={handlePress}
			/>
		</Animated.View>
	);
}
BottomSheetOverlayPressArea.displayName = "DelacourUI.BottomSheet.Overlay.PressArea";

// A style rather than a class: the height beside it is an animated value, and the
// two have to arrive on the same node.
const styles = StyleSheet.create({
	pressArea: { left: 0, position: "absolute", right: 0, top: 0 },
});

import { Children, isValidElement, type ReactElement, type ReactNode, useMemo } from "react";
import { BottomSheetPortalProvider } from "./bottom-sheet.context";
import { BottomSheetOverlay } from "./bottom-sheet-overlay";

export type BottomSheetPortalProps = {
	children?: ReactNode;
};

/**
 * Everything that draws above the app once the sheet is open.
 *
 * It renders no view of its own, and it does not portal anything either —
 * `BottomSheetModal` already hosts itself in the `BottomSheetModalProvider` that
 * `DelacourProvider` mounts innermost. What this part does is one thing:
 * **it lifts the `BottomSheet.Overlay` out of its own children** and publishes it
 * on context, so `BottomSheet.Container` can clone it into gorhom's
 * `backdropComponent` slot.
 *
 * That indirection buys the anatomy. The scrim and the sheet are siblings on
 * screen, so they read best as siblings in the tree — but gorhom takes the scrim
 * as a render prop, and a component cannot hand a prop to a sibling. This is the
 * seam where the two shapes are reconciled, and it is why the part exists at all
 * rather than the container simply taking a `backdrop` prop.
 *
 * @example
 * <BottomSheet.Portal>
 *   <BottomSheet.Overlay />
 *   <BottomSheet.Container>{…}</BottomSheet.Container>
 * </BottomSheet.Portal>
 */
export function BottomSheetPortal({ children }: BottomSheetPortalProps): ReactElement {
	const { content, overlay } = useMemo(() => hoistOverlay(children), [children]);
	const value = useMemo(() => ({ overlay }), [overlay]);

	return <BottomSheetPortalProvider value={value}>{content}</BottomSheetPortalProvider>;
}
BottomSheetPortal.displayName = "DelacourUI.BottomSheet.Portal";

/**
 * Splits a portal's children into the scrim and everything else.
 *
 * Lives here rather than with the parts: it is the portal that lifts its own
 * children, and importing it from `bottom-sheet-overlay.tsx` would close a cycle.
 * The same rule that keeps `withIndicator` in `radio.tsx`. See AGENTS.md.
 *
 * A second overlay is dropped rather than rendered — there is one
 * `backdropComponent` slot to clone into, and silently drawing two scrims at
 * different opacities is worse than the warning.
 */
function hoistOverlay(children: ReactNode): { content: ReactNode; overlay: ReactElement | null } {
	const items = Children.toArray(children);
	const content: ReactNode[] = [];
	let overlay: ReactElement | null = null;
	let seen = 0;

	for (const child of items) {
		if (isValidElement(child) && child.type === BottomSheetOverlay) {
			seen += 1;
			overlay ??= child;
			continue;
		}
		content.push(child);
	}

	if (process.env.NODE_ENV !== "production" && seen > 1) {
		console.warn(
			`BottomSheet.Portal: ${seen} <BottomSheet.Overlay> elements were written; only the first is drawn. A sheet has one backdrop.`
		);
	}

	return { content, overlay };
}

import { BottomSheetScrollView as GorhomBottomSheetScrollView } from "@gorhom/bottom-sheet";
import type { ComponentProps, ReactElement, ReactNode } from "react";
import { View } from "react-native";
import Animated, { useAnimatedStyle } from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { withUniwind } from "uniwind";
import { cn } from "@registry/lib/cn";
import { useBottomSheetContainerContext } from "./bottom-sheet.context";
import { BOTTOM_SHEET_FOOTER_GAP, bottomSheetVariants, resolveSheetBottomInset } from "./bottom-sheet.variants";

type GorhomScrollViewProps = ComponentProps<typeof GorhomBottomSheetScrollView>;

/**
 * The one class prop this file uses, restated so the props survive the wrapper.
 *
 * `withUniwind`'s return type maps over a component's props, and over a
 * scrollable's animated ones it collapses to a single entry — `data`,
 * `contentContainerStyle` and the rest would all check against nothing. Writing
 * the signature out keeps them, the way `Screen.LegendList` already has to.
 *
 * `contentContainerClassName` is deliberately absent even though the wrapper adds
 * one at runtime: passing it would put a second writer on `contentContainerStyle`
 * and cost the safe-area band — see the component's doc comment.
 */
type StyledScrollViewComponent = (props: GorhomScrollViewProps & { className?: string }) => ReactElement | null;

// Third-party, so `className` needs the wrapper — and it has to be built at
// module scope or every render mints a new component type and remounts the list.
const StyledScrollView = withUniwind(GorhomBottomSheetScrollView) as unknown as StyledScrollViewComponent;

export type BottomSheetScrollViewProps = Omit<
	GorhomScrollViewProps,
	"children" | "contentContainerStyle" | "enableFooterMarginAdjustment"
> & {
	className?: string;
	/** Classes for the padded box the children sit in. */
	contentContainerClassName?: string;
	children?: ReactNode;
};

/**
 * A scrolling body for a sheet taller than its snap point.
 *
 * Use this rather than a plain `ScrollView`: gorhom's scrollable and the sheet's
 * pan negotiate with each other, so dragging a list that is already at its top
 * moves the sheet instead of fighting it. A React Native `ScrollView` in here has
 * no such arrangement, and the sheet stops responding to a drag over the list.
 *
 * **It needs a height to scroll within.** With `enableDynamicSizing` left on, the
 * sheet grows to whatever the content measures and there is nothing to scroll —
 * pass `enableDynamicSizing={false}` and explicit `snapPoints` on the
 * `BottomSheet.Container` around it.
 *
 * The classes go on an inner `View`, not on gorhom's own content container, and
 * that is not tidiness: uniwind compiles a `contentContainerClassName` into an
 * *array* alongside any `contentContainerStyle`, and the two then fight over the
 * one style this component has to own — the safe-area band. One writer for it.
 *
 * A pinned footer is reserved by a spacer at the end of the content rather than
 * by gorhom's `enableFooterMarginAdjustment`, which routes the footer's measured
 * height through React state and would commit a render on every frame of the
 * keyboard animation. See `BottomSheet.Content` for the whole reasoning.
 *
 * @example
 * <BottomSheet.Container enableDynamicSizing={false} snapPoints={["60%", "90%"]}>
 *   <BottomSheet.ScrollView>{rows}</BottomSheet.ScrollView>
 * </BottomSheet.Container>
 */
export function BottomSheetScrollView({
	className,
	contentContainerClassName,
	children,
	...props
}: BottomSheetScrollViewProps): ReactElement {
	const container = useBottomSheetContainerContext();
	const { bottom } = useSafeAreaInsets();
	const hasStickyFooter = container?.hasStickyFooter ?? false;
	const footerHeight = container?.footerHeight;

	const reserve = useAnimatedStyle(() => ({
		height: footerHeight === undefined ? 0 : footerHeight.value + BOTTOM_SHEET_FOOTER_GAP,
	}));

	return (
		<StyledScrollView
			className={cn(className)}
			contentContainerStyle={{ paddingBottom: resolveSheetBottomInset({ bottom, hasStickyFooter }) }}
			{...props}
		>
			<View className={bottomSheetVariants().scrollContent({ className: contentContainerClassName })}>{children}</View>
			{hasStickyFooter ? <Animated.View style={reserve} /> : null}
		</StyledScrollView>
	);
}
BottomSheetScrollView.displayName = "DelacourUI.BottomSheet.ScrollView";

import type { ReactElement } from "react";
import { Text, type TextPresetProps } from "@registry/ui/text";
import { bottomSheetVariants } from "./bottom-sheet.variants";

export type BottomSheetTitleProps = TextPresetProps;

/**
 * The sheet's heading.
 *
 * *Is* a `Text.Header` — it renders the preset and adds layout, never a size or a
 * weight of its own, the same trade `Field.Label` makes with `Text.Label`. A
 * `text-lg font-semibold` here would be a second definition of that preset which
 * could drift from it, and the tests assert the slot carries neither.
 *
 * The preset already announces itself as a heading, so a screen reader reaches
 * the sheet's purpose first with nothing said at the call site.
 *
 * @example
 * <BottomSheet.Title>Keep yourself safe</BottomSheet.Title>
 */
export function BottomSheetTitle({ className, ...props }: BottomSheetTitleProps): ReactElement {
	return <Text.Header className={bottomSheetVariants().title({ className })} {...props} />;
}
BottomSheetTitle.displayName = "DelacourUI.BottomSheet.Title";

import { type ReactElement, useCallback } from "react";
import { Slot } from "@registry/lib/slot";
import { Pressable, type PressableProps } from "@registry/ui/pressable";
import { useBottomSheetPart } from "./bottom-sheet.context";

export type BottomSheetTriggerProps = PressableProps;

/**
 * The control that opens the sheet.
 *
 * On its own it is a `Pressable`, so `feedback`, `haptic` and the rest are
 * inherited rather than restated. It opens through the same state a controlled
 * `isOpen` drives, so a sheet can be opened from here and from elsewhere on the
 * same screen without the two disagreeing, and a caller's own `onPress` still
 * runs after the open.
 *
 * **`asChild` donates the press rather than wrapping the child**, which is where
 * it differs from `Pressable`'s own. `Pressable asChild` keeps its gesture and
 * renders the child inside it — correct for a child that is not itself a
 * control, and wrong here, because the thing anyone wraps in a trigger is a
 * `Button`. Two tap gestures in an ancestor/descendant pair are not
 * simultaneous, so Gesture Handler gives the press to the DESCENDANT: the
 * button's own detector wins, fires the `onPress` it does not have, and the
 * sheet never opens. Nothing announces this — the press simply does nothing.
 *
 * So the trigger hands its `onPress` down as a prop instead, through `Slot`,
 * which chains it ahead of any the child already had. The child keeps its own
 * gesture, its own feedback and its own haptic, and there is still no extra view
 * in the tree.
 *
 * The corollary: **the child has to be something that handles `onPress`.** A
 * `View` or a `Text` takes the prop and ignores it. Wrap a `Button`, a
 * `ListGroup.Item`, or anything else built on `Pressable`.
 *
 * @example
 * <BottomSheet.Trigger asChild>
 *   <Button variant="secondary">Open</Button>
 * </BottomSheet.Trigger>
 *
 * @example
 * // No asChild: the trigger is its own pressable.
 * <BottomSheet.Trigger className="p-4">
 *   <Text>Open</Text>
 * </BottomSheet.Trigger>
 */
export function BottomSheetTrigger({
	asChild = false,
	children,
	onPress,
	...props
}: BottomSheetTriggerProps): ReactElement {
	const { open } = useBottomSheetPart("BottomSheet.Trigger");

	const handlePress = useCallback(() => {
		open();
		onPress?.();
	}, [onPress, open]);

	if (asChild) {
		return (
			<Slot onPress={handlePress} {...props}>
				{children}
			</Slot>
		);
	}

	return (
		<Pressable onPress={handlePress} {...props}>
			{children}
		</Pressable>
	);
}
BottomSheetTrigger.displayName = "DelacourUI.BottomSheet.Trigger";

import type { BottomSheetModal } from "@gorhom/bottom-sheet";
import { type ComponentRef, createContext, type ReactElement, type ReactNode, type RefObject, use } from "react";
import type { SharedValue } from "react-native-reanimated";

/**
 * The imperative handle a `BottomSheetModal` exposes.
 *
 * Derived from the component rather than imported by name: gorhom re-exports the
 * modal's *value* from its package root but not the `BottomSheetModalMethods`
 * type behind its ref, and reaching into `lib/typescript/` for one would pin this
 * package to a path that is not part of that package's public surface.
 */
export type BottomSheetHandle = ComponentRef<typeof BottomSheetModal>;

export type BottomSheetContextValue = {
	isOpen: boolean;
	/** The controllable-state setter. Reports upward whether controlled or not. */
	setOpen: (isOpen: boolean) => void;
	open: () => void;
	close: () => void;
	/**
	 * The modal's handle, for the imperative calls that have no declarative form —
	 * `snapToIndex`, `expand`, `collapse`. Presenting and dismissing are driven by
	 * `isOpen` instead, so a caller never has to keep two sources in step.
	 */
	sheetRef: RefObject<BottomSheetHandle | null>;
};

const BottomSheetContext = createContext<BottomSheetContextValue | null>(null);

export function BottomSheetProvider({
	value,
	children,
}: {
	value: BottomSheetContextValue;
	children: ReactNode;
}): ReactElement {
	return <BottomSheetContext value={value}>{children}</BottomSheetContext>;
}
BottomSheetProvider.displayName = "DelacourUI.BottomSheet.Provider";

/** The sheet's state, or `null` outside one. For a component that works either way. */
export function useBottomSheetContext(): BottomSheetContextValue | null {
	return use(BottomSheetContext);
}

/**
 * The enclosing sheet's open state and controls.
 *
 * Reach for this to drive a sheet from a control of your own — a row that closes
 * it, a button that snaps it somewhere — without threading props down.
 */
export function useBottomSheet(): BottomSheetContextValue {
	const context = use(BottomSheetContext);
	if (context === null) throw new Error("useBottomSheet must be called inside a <BottomSheet>.");
	return context;
}

/** The same read, with a message naming the part that is misplaced. Internal. */
export function useBottomSheetPart(component: string): BottomSheetContextValue {
	const context = use(BottomSheetContext);
	if (context === null) throw new Error(`${component} must be rendered inside a <BottomSheet>.`);
	return context;
}

export type BottomSheetPortalContextValue = {
	/**
	 * The `BottomSheet.Overlay` element the portal lifted out of its own children,
	 * or `null` when none was written.
	 *
	 * gorhom takes the scrim as a `backdropComponent` render prop rather than as a
	 * child, so the element cannot be rendered where it was declared. The portal
	 * publishes it here and `BottomSheet.Container` clones it into that slot.
	 */
	overlay: ReactElement | null;
};

const BottomSheetPortalContext = createContext<BottomSheetPortalContextValue | null>(null);

export function BottomSheetPortalProvider({
	value,
	children,
}: {
	value: BottomSheetPortalContextValue;
	children: ReactNode;
}): ReactElement {
	return <BottomSheetPortalContext value={value}>{children}</BottomSheetPortalContext>;
}
BottomSheetPortalProvider.displayName = "DelacourUI.BottomSheet.Portal.Provider";

/** What the enclosing portal lifted out, or `null` for a container written without one. */
export function useBottomSheetPortalContext(): BottomSheetPortalContextValue | null {
	return use(BottomSheetPortalContext);
}

export type BottomSheetContainerContextValue = {
	/**
	 * Whether a pinned footer is drawing at the bottom of this sheet.
	 *
	 * `BottomSheet.Content` reads it to decide whether the safe-area band is its
	 * to apply. Exactly one part takes it: both applying leaves a gap the height
	 * of the home indicator between the content and the footer.
	 */
	hasStickyFooter: boolean;
	/**
	 * What a pinned footer covers, measured, in points.
	 *
	 * A shared value rather than state: it changes on every frame of the keyboard
	 * animation as the footer gives up its safe-area band, and the body reserves it
	 * with an animated spacer. Routing that through React would commit a dozen
	 * renders per keystroke's worth of keyboard travel. `Screen` publishes its own
	 * chrome the same way.
	 *
	 * Zero when there is no pinned footer.
	 */
	footerHeight: SharedValue<number>;
};

const BottomSheetContainerContext = createContext<BottomSheetContainerContextValue | null>(null);

export function BottomSheetContainerProvider({
	value,
	children,
}: {
	value: BottomSheetContainerContextValue;
	children: ReactNode;
}): ReactElement {
	return <BottomSheetContainerContext value={value}>{children}</BottomSheetContainerContext>;
}
BottomSheetContainerProvider.displayName = "DelacourUI.BottomSheet.Container.Provider";

/** The enclosing container's layout facts, or `null` outside one. */
export function useBottomSheetContainerContext(): BottomSheetContainerContextValue | null {
	return use(BottomSheetContainerContext);
}

import { type ReactElement, type ReactNode, useCallback, useMemo, useRef } from "react";
import { useControllableState } from "@registry/hooks/use-controllable-state";
import { type BottomSheetContextValue, type BottomSheetHandle, BottomSheetProvider } from "./bottom-sheet.context";
import { BottomSheetClose } from "./bottom-sheet-close";
import { BottomSheetContainer } from "./bottom-sheet-container";
import { BottomSheetContent } from "./bottom-sheet-content";
import { BottomSheetDescription } from "./bottom-sheet-description";
import { BottomSheetFooter } from "./bottom-sheet-footer";
import { BottomSheetOverlay } from "./bottom-sheet-overlay";
import { BottomSheetPortal } from "./bottom-sheet-portal";
import { BottomSheetScrollView } from "./bottom-sheet-scroll-view";
import { BottomSheetTitle } from "./bottom-sheet-title";
import { BottomSheetTrigger } from "./bottom-sheet-trigger";

export type BottomSheetProps = {
	children?: ReactNode;
	/** Controlled open state. Leave it off and the sheet holds its own. */
	isOpen?: boolean;
	/** Initial open state while uncontrolled. */
	defaultOpen?: boolean;
	/**
	 * Called whenever the sheet opens or closes — by a trigger, a swipe down, a
	 * press on the backdrop, `BottomSheet.Close`, or a controlled `isOpen`.
	 *
	 * One callback for every path, deliberately. gorhom's own `onClose` fires for
	 * the gesture alone, which is the shape that makes a caller wire three
	 * handlers and still miss one.
	 */
	onOpenChange?: (isOpen: boolean) => void;
};

function BottomSheetRoot({ children, defaultOpen = false, isOpen, onOpenChange }: BottomSheetProps): ReactElement {
	const sheetRef = useRef<BottomSheetHandle | null>(null);
	const [isSheetOpen, setOpen] = useControllableState<boolean>({
		defaultValue: defaultOpen,
		onChange: onOpenChange,
		value: isOpen,
	});

	const open = useCallback(() => setOpen(true), [setOpen]);
	const close = useCallback(() => setOpen(false), [setOpen]);

	const context = useMemo<BottomSheetContextValue>(
		() => ({ close, isOpen: isSheetOpen, open, setOpen, sheetRef }),
		[close, isSheetOpen, open, setOpen]
	);

	return <BottomSheetProvider value={context}>{children}</BottomSheetProvider>;
}

/**
 * A panel that slides up from the bottom of the screen, over everything.
 *
 * The library's first overlay, built on `@gorhom/bottom-sheet`'s modal. It
 * renders no view of its own — it owns the open state and hands it to the parts
 * through context, so a trigger anywhere inside can open a sheet declared
 * anywhere else in the same tree.
 *
 * **The app must mount `DelacourProvider` at its root.** The sheet hosts itself in
 * the `BottomSheetModalProvider` that provider's innermost layer supplies, and it
 * needs the gesture root above it for the pan.
 *
 * **Two parts are not drawn where they are written.** `BottomSheet.Overlay` and a
 * `BottomSheet.Footer sticky` are lifted out of the tree and handed to gorhom as
 * render props — see `BottomSheet.Portal` and `BottomSheet.Container` for why the
 * anatomy is worth that. Everything else renders in place.
 *
 * Controlled or not, from one hook: pass `isOpen` and `onOpenChange` to own the
 * state, or nothing at all and let the sheet hold it. Which mode is in play is
 * locked in on first render.
 *
 * @example
 * <BottomSheet>
 *   <BottomSheet.Trigger asChild>
 *     <Button variant="secondary">Open</Button>
 *   </BottomSheet.Trigger>
 *   <BottomSheet.Portal>
 *     <BottomSheet.Overlay />
 *     <BottomSheet.Container>
 *       <BottomSheet.Content>
 *         <BottomSheet.Close />
 *         <BottomSheet.Title>Keep yourself safe</BottomSheet.Title>
 *         <BottomSheet.Description>Update to the latest version.</BottomSheet.Description>
 *       </BottomSheet.Content>
 *       <BottomSheet.Footer sticky>
 *         <Button onPress={update}>Update now</Button>
 *       </BottomSheet.Footer>
 *     </BottomSheet.Container>
 *   </BottomSheet.Portal>
 * </BottomSheet>
 *
 * @example
 * // Controlled, and opened from somewhere other than a trigger.
 * <BottomSheet isOpen={isOpen} onOpenChange={setOpen}>
 *   <BottomSheet.Portal>
 *     <BottomSheet.Overlay />
 *     <BottomSheet.Container>
 *       <BottomSheet.Content>{…}</BottomSheet.Content>
 *     </BottomSheet.Container>
 *   </BottomSheet.Portal>
 * </BottomSheet>
 */
export const BottomSheet = Object.assign(BottomSheetRoot, {
	/** The control that opens the sheet. `asChild` to make a `Button` the trigger. */
	Trigger: BottomSheetTrigger,
	/** Everything drawn above the app. Lifts the overlay out to the container. */
	Portal: BottomSheetPortal,
	/** The scrim. Written beside the container, drawn as its backdrop. */
	Overlay: BottomSheetOverlay,
	/** The sheet itself. Every gorhom prop passes through it. */
	Container: BottomSheetContainer,
	/** The sheet's body, sized to itself under `enableDynamicSizing`. */
	Content: BottomSheetContent,
	/** A scrolling body. Needs `enableDynamicSizing={false}` and snap points. */
	ScrollView: BottomSheetScrollView,
	/** The dismiss control, positioned out of the content's flow. */
	Close: BottomSheetClose,
	/** The sheet's heading — a `Text.Header` with the close control's clearance. */
	Title: BottomSheetTitle,
	/** Supporting copy under the title — a muted `Text.Paragraph`. */
	Description: BottomSheetDescription,
	/** Controls at the bottom. `sticky` pins them above the keyboard. */
	Footer: BottomSheetFooter,
	displayName: "DelacourUI.BottomSheet",
});

import type { VariantProps } from "tailwind-variants";
import { tv } from "@registry/lib/tv";

/**
 * The scrim token, named here so a test can pin it against `theme.css`.
 *
 * A token rather than a `bg-black/50` written at a call site: the two theme
 * variants carry different alphas, because a pure-black scrim over a near-black
 * dark theme is nearly invisible.
 */
export const BOTTOM_SHEET_OVERLAY_TOKEN = "overlay";

/**
 * The backdrop's opacity at full appearance.
 *
 * **1, not gorhom's 0.5.** The alpha lives in `--color-overlay`, so leaving the
 * library default in place would multiply the two and land the scrim at roughly
 * a fifth of what the theme asked for. One source for the alpha, and it is the
 * token — which is also what lets the two theme variants differ.
 */
export const BOTTOM_SHEET_OVERLAY_OPACITY = 1;

/**
 * The snap indices the scrim appears and disappears on.
 *
 * gorhom defaults to `{ appearsOnIndex: 1, disappearsOnIndex: 0 }`, which suits
 * a persistent sheet that rests collapsed on the screen and only dims the app
 * once it is expanded. A modal sheet has no resting state: it is either
 * presented or gone, so the scrim belongs from the FIRST snap point (`0`) and
 * is only absent when the sheet is closed (`-1`).
 */
export const BOTTOM_SHEET_BACKDROP_INDICES = { appearsOnIndex: 0, disappearsOnIndex: -1 } as const;

/**
 * Keyboard behaviour every `BottomSheet.Container` starts from.
 *
 * A const rather than three defaults spelled inline, so `bun test` pins them and
 * a retune is one edit rather than three.
 *
 * - `interactive` — the sheet grows to keep its content above the keyboard,
 *   following it frame by frame rather than snapping once it has settled.
 * - `restore` — blurring returns the sheet to the snap point it was on. Without
 *   it a sheet that grew for the keyboard stays grown over empty screen.
 * - `adjustResize` — gorhom's own default is `adjustPan`, which leaves the
 *   Android window height alone and slides the whole view up, so a sheet's
 *   footer lands off-screen. `resize` is already what Expo configures and what
 *   `KeyboardProvider` requires, so this is the value that matches the window.
 */
export const BOTTOM_SHEET_KEYBOARD_DEFAULTS = {
	keyboardBehavior: "interactive",
	keyboardBlurBehavior: "restore",
	android_keyboardInputMode: "adjustResize",
} as const;

/**
 * Slop around `BottomSheet.Close`.
